package com.ghatana.media.launcher;

import javax.imageio.ImageIO;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.TimeUnit;

/**
 * Real input for the J-05 vision tracking journey: a 640x360 video generated by FFmpeg in which a red car sprite moves
 * right and a person sprite moves down over three seconds on a white background with the text GHATANA, with a known
 * analytic ground truth. The motion is produced by FFmpeg's overlay filter from the frame timestamp {@code t}, so the
 * true box of each object at any source PTS is {@code car x = 20 + 90 t}, {@code person y = 40 + 50 t}. The variable
 * frame rate variant drops frames after the overlay, so the same truth holds at irregular presentation times.
 */
final class TrackingVideoFixture {
    static final int WIDTH = 640;
    static final int HEIGHT = 360;
    static final int CAR_WIDTH = 160;
    static final int CAR_HEIGHT = 77;
    static final int PERSON_WIDTH = 68;
    static final int PERSON_HEIGHT = 151;
    static final int CAR_Y = 250;
    static final int PERSON_X = 500;

    /** Ground-truth top-left of the car sprite at presentation time {@code seconds}. */
    static double[] carBox(double seconds) { return new double[] {20 + 90 * seconds, CAR_Y, CAR_WIDTH, CAR_HEIGHT}; }

    static double[] personBox(double seconds) {
        return new double[] {PERSON_X, 40 + 50 * seconds, PERSON_WIDTH, PERSON_HEIGHT};
    }

    private TrackingVideoFixture() { }

    /** Generates the mp4 with FFmpeg. {@code vfr} drops frames n % 7 in {5,6} so PTS spacing is irregular. */
    static byte[] generate(Path ffmpeg, Path work, boolean vfr) throws Exception {
        Path bg = work.resolve("bg.png");
        Path car = work.resolve("car.png");
        Path person = work.resolve("person.png");
        Files.write(bg, background());
        Files.write(car, carSprite());
        Files.write(person, personSprite());
        Path out = work.resolve(vfr ? "vfr.mp4" : "cfr.mp4");
        String chain = "[0:v][1:v]overlay=x='20+90*t':y=" + CAR_Y + ":format=rgb[a];"
                + "[a][2:v]overlay=x=" + PERSON_X + ":y='40+50*t':format=rgb[b];[b]format=yuv420p"
                + (vfr ? ",select='lt(mod(n\\,7)\\,5)'" : "") + "[out]";
        List<String> command = new java.util.ArrayList<>(List.of(ffmpeg.toString(), "-nostdin", "-v", "error",
                "-loop", "1", "-framerate", "10", "-t", "3", "-i", bg.toString(),
                "-i", car.toString(), "-i", person.toString(), "-filter_complex", chain, "-map", "[out]"));
        // CFR pins the 10 fps clock; VFR keeps the irregular PTS left by the frame drop.
        command.addAll(vfr ? List.of("-fps_mode", "vfr") : List.of("-fps_mode", "cfr", "-r", "10"));
        command.addAll(List.of("-c:v", "libx264", "-preset", "veryfast", "-crf", "16", "-pix_fmt", "yuv420p",
                "-movflags", "+faststart", "-y", out.toString()));
        Process process = new ProcessBuilder(command).redirectErrorStream(true).start();
        byte[] log = process.getInputStream().readAllBytes();
        if (!process.waitFor(120, TimeUnit.SECONDS) || process.exitValue() != 0 || !Files.isRegularFile(out)) {
            throw new IllegalStateException("ffmpeg could not generate the test video: " + new String(log));
        }
        return Files.readAllBytes(out);
    }

    /** ffprobe frame PTS values (stream ticks, PTS order) and the stream time base, independently of the product. */
    static record Probe(long timeBaseNum, long timeBaseDen, List<Long> pts) { }

    static Probe probe(Path ffprobe, Path video) throws Exception {
        Process process = new ProcessBuilder(ffprobe.toString(), "-v", "error", "-select_streams", "v:0",
                "-show_entries", "frame=pts:stream=time_base", "-of", "csv=p=0", video.toString())
                .redirectErrorStream(true).start();
        String text = new String(process.getInputStream().readAllBytes());
        if (!process.waitFor(60, TimeUnit.SECONDS) || process.exitValue() != 0) {
            throw new IllegalStateException("ffprobe failed: " + text);
        }
        long num = 0;
        long den = 0;
        List<Long> pts = new java.util.ArrayList<>();
        for (String line : text.split("\\R")) {
            line = line.strip();
            // csv rows may carry trailing separators for empty fields (for example side data): keep the first field.
            if (line.contains(",")) line = line.substring(0, line.indexOf(',')).strip();
            if (line.isEmpty()) continue;
            if (line.contains("/")) {
                String[] parts = line.split("/");
                num = Long.parseLong(parts[0]);
                den = Long.parseLong(parts[1]);
            } else {
                pts.add(Long.parseLong(line));
            }
        }
        java.util.Collections.sort(pts);
        return new Probe(num, den, pts);
    }

    static byte[] background() throws IOException {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g.setColor(Color.WHITE);
            g.fillRect(0, 0, WIDTH, HEIGHT);
            g.setColor(Color.BLACK);
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 56));
            g.drawString("GHATANA", 20, 70);
        } finally {
            g.dispose();
        }
        return png(image);
    }

    static byte[] carSprite() throws IOException {
        BufferedImage image = new BufferedImage(CAR_WIDTH, CAR_HEIGHT, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            double w = CAR_WIDTH;
            double h = 70;
            Color body = new Color(200, 30, 30);
            g.setColor(body);
            g.fillRoundRect(0, (int) (h * 0.4), (int) w, (int) (h * 0.45), 8, 8);
            g.fillPolygon(new int[] {(int) (w * 0.2), (int) (w * 0.32), (int) (w * 0.7), (int) (w * 0.85)},
                    new int[] {(int) (h * 0.4), 0, 0, (int) (h * 0.4)}, 4);
            g.setColor(new Color(170, 210, 240));
            g.fillPolygon(new int[] {(int) (w * 0.27), (int) (w * 0.35), (int) (w * 0.48), (int) (w * 0.48)},
                    new int[] {(int) (h * 0.38), (int) (h * 0.1), (int) (h * 0.1), (int) (h * 0.38)}, 4);
            g.fillPolygon(new int[] {(int) (w * 0.52), (int) (w * 0.52), (int) (w * 0.67), (int) (w * 0.8)},
                    new int[] {(int) (h * 0.38), (int) (h * 0.1), (int) (h * 0.1), (int) (h * 0.38)}, 4);
            for (double cx : new double[] {w * 0.25, w * 0.75}) {
                int cy = (int) (h * 0.85);
                g.setColor(new Color(20, 20, 20));
                g.fillOval((int) cx - 17, cy - 17, 34, 34);
                g.setColor(new Color(180, 180, 180));
                g.fillOval((int) cx - 7, cy - 7, 14, 14);
            }
        } finally {
            g.dispose();
        }
        return png(image);
    }

    static byte[] personSprite() throws IOException {
        BufferedImage image = new BufferedImage(PERSON_WIDTH, PERSON_HEIGHT, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int cx = PERSON_WIDTH / 2;
            Color shirt = new Color(30, 60, 200);
            g.setColor(new Color(235, 190, 150));
            g.fillOval(cx - 14, 0, 28, 28);
            g.setColor(shirt);
            g.fillRect(cx - 20, 30, 40, 60);
            g.fillRect(cx - 34, 32, 14, 53);
            g.fillRect(cx + 20, 32, 14, 53);
            g.setColor(new Color(40, 40, 70));
            g.fillRect(cx - 18, 90, 16, 60);
            g.fillRect(cx + 2, 90, 16, 60);
        } finally {
            g.dispose();
        }
        return png(image);
    }

    private static byte[] png(BufferedImage image) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        ImageIO.write(image, "png", out);
        return out.toByteArray();
    }

    /** IoU of two {x, y, w, h} boxes. */
    static double iou(double[] a, double[] b) {
        double ix = Math.max(0, Math.min(a[0] + a[2], b[0] + b[2]) - Math.max(a[0], b[0]));
        double iy = Math.max(0, Math.min(a[1] + a[3], b[1] + b[3]) - Math.max(a[1], b[1]));
        double inter = ix * iy;
        return inter / (a[2] * a[3] + b[2] * b[3] - inter);
    }

    static double centerError(double[] a, double[] b) {
        return Math.hypot(a[0] + a[2] / 2 - b[0] - b[2] / 2, a[1] + a[3] / 2 - b[1] - b[3] / 2);
    }
}
